Response* LoginHandler::callback(Request* req) {
    try {
        string id = req->getBodyParam("id");
        string password = req->getBodyParam("password");

        system->login(id, password);
        Response* res = new Response();

        if (system->entered_person.user == STUDENT) 
            res = Response::redirect("/student");
        if (system->entered_person.user == PROFESSOR)
            res = Response::redirect("/professor");
        if (system->entered_person.user == MANAGER)
            res = Response::redirect("/manager");

        return res;
    }

    catch (Request_Exception ex) {
        Response* res = Response::redirect("/error1");
        return res;
    }
    catch (NotFound_Exception ex) {
        Response* res = Response::redirect("/error2");
        return res;
    }
    catch (Permission_Exception ex) {
        Response* res = Response::redirect("/error3");
        return res;
    }
}

